"""Authored static pages: crawlable HTML, page-specific art, no client-side router."""
from pathlib import Path
from bs4 import BeautifulSoup
import json,html
P=Path('public');ORIGIN='https://www.veriburada.com'
HOME=BeautifulSoup((P/'index.html').read_text(encoding='utf-8'),'html.parser')
MENU=Path('research/shared-menu.html').read_text(encoding='utf-8')
def absolute(fragment):
 s=BeautifulSoup(str(fragment),'html.parser')
 for el in s.select('[src],[href],[poster],[data-src]'):
  for attr in ['src','href','poster','data-src']:
   if el.has_attr(attr):
    v=el[attr]
    if v.startswith('#'):el[attr]='/'+v
    elif not v.startswith(('/','https:','http:','mailto:','data:')):el[attr]='/'+v
 return str(s)
HEADER=absolute(HOME.select_one('.header'));FOOTER=absolute(HOME.select_one('.footer'))
pages=[]
def link(path,text):return f'<a class="editorial-link" href="/{path}/">{text} <span>↗</span></a>'
def block(title,body):return f'<section class="reading-block"><h2>{title}</h2>{body}</section>'
def paras(*texts):return ''.join('<p>'+t+'</p>' for t in texts)
def cards(items):return '<div class="editorial-cards">'+''.join(f'<article><span class="card-index">0{i+1}</span><h3>{t}</h3><p>{b}</p>{link(p,c) if p else ""}</article>' for i,(t,b,p,c) in enumerate(items))+'</div>'
def faq(items):return '<div class="editorial-faq">'+''.join(f'<details><summary>{q}<span>+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'
def add(slug,title,description,h1,lead,body,scene=None,**kw):pages.append(dict(slug=slug,title=title,description=description,h1=h1,lead=lead,body=body,scene=scene,**kw))
records=[('Atölye Mimarlık','Mimarlık ofisi','atolyemimarlik.example','Meşrutiyet Cd. No: 12'),('Form Tasarım','Mimarlık ofisi','formtasarim.example','Sıraselviler Cd. No: 24'),('Studio Mimarlık','Mimarlık ofisi','studiomimarlik.example','Boğazkesen Cd. No: 8'),('Mekân Atölyesi','Mimarlık ofisi','mekanatolyesi.example','Kumbaracı Yokuşu No: 16'),('Pera Mimarlık','Mimarlık ofisi','peramimarlik.example','İstiklal Cd. No: 32')]
def sheet():
 return '<div class="directory-scroll" role="region" aria-label="Dolu örnek işletme listesi" tabindex="0"><table class="directory-table"><caption>Örnek işletme listesi · Beyoğlu, İstanbul</caption><thead><tr><th scope="col">İşletme</th><th scope="col">Telefon</th><th scope="col">Web sitesi</th><th scope="col">Adres</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row"><b>{n[0]}</b><span>{n}<small>{typ}</small></span></th><td>+90 (212) 000 10 0{i+1}</td><td>{web}</td><td>{address}, Beyoğlu</td></tr>' for i,(n,typ,web,address) in enumerate(records))+'</tbody></table></div>'
def scene(kind):
 if kind=='story':return '<div class="page-film" data-page-film><iframe src="/map-demo.html?story&portrait" title="Bölge seçiminden toplu listeye: örnek ürün anlatımı" tabindex="-1" loading="lazy"></iframe></div><p class="scene-note">Ürün akışını anlatan örnek kayıtlar.</p>'
 if kind=='agency':
  return '<div class="page-agency" data-page-scene="agency"><div class="scene-top"><b>Web araştırmanız</b><span>Restoranlar · Beyoğlu</span></div><div class="page-agency-grid">'+''.join(f'<article><div class="mini-site-nav"><b>{name}</b><span>Menü · İletişim</span></div><div class="mini-site-photo"><img src="/media/{photo}.webp" width="1100" height="825" alt="Restoran iç mekânı, temsili fotoğraf"/><div><small>BEYOĞLU, İSTANBUL</small><strong>{heading}</strong><span>Menüyü keşfedin ↗</span></div></div><div class="page-site-fields"><b>{domain}.example</b><span>+90 (212) 000 10 0{i+1}</span><span>{address} · Beyoğlu</span></div></article>' for i,(name,photo,heading,domain,address) in enumerate([('Pera Mutfak','restaurant','Mevsimden<br>sofranıza.','peramutfak','Meşrutiyet Cd. No: 12'),('Sahil Restoran','dining','İyi yemek.<br>Güzel sohbet.','sahilrestoran','Kılıçali Paşa Mah. No: 8')]))+'</div><p class="scene-note">Örnek web tasarımları ve işletme bilgileri.</p></div>'
 if kind=='local':return '<div class="page-map" data-page-scene="local"><div class="page-map-query"><span>⌕</span><div><small>Beyoğlu, İstanbul</small><b>Kafeler ve restoranlar</b></div><i>↗</i></div>'+''.join(f'<div class="page-map-pin pin-{i}" data-pin><b>{i+1}</b><span>{name}</span></div>' for i,name in enumerate(['Köşe Kahve','Mahalle Sofrası','Gün Işığı Kafe']))+'<div class="page-map-result"><span class="scene-indicator"></span><b>3 işletme, tek çalışma listesi.</b><span>Telefon · Web sitesi · Adres</span></div><small class="map-credit">© OpenStreetMap contributors · Harita örnektir.</small></div>'
 if kind=='install':return '<div class="page-install" data-page-scene="install"><div class="scene-top"><b>Tarayıcınız</b><span>Uzantılar ⊞</span></div><div class="page-install-canvas"><div class="install-package" data-step><span>ZIP</span><b>Veri Burada<small>Eklenti dosyası</small></b><i>✓</i></div><svg class="install-route" viewBox="0 0 500 240" aria-hidden="true"><path d="M115 135H235Q260 135 260 110V70Q260 48 285 48H405" pathLength="1"/></svg><div class="extension-popup" data-step><img src="/brand-emblem-small.webp" alt="" width="50" height="50"/><b>Veri Burada</b><span>Tarayıcınıza hazır.</span><div>İstanbul / Beyoğlu<br><strong>Mimarlık ofisleri</strong></div></div></div><p class="scene-note">Dosyayı açın → Uzantılara yükleyin → Aramanızı başlatın.</p></div>'
 if kind in ['sales','fields','batch','csv']:
  names=['Gülüş Diş Kliniği','Merkez Ağız ve Diş','İnci Diş Kliniği'] if kind=='sales' else [r[0] for r in records[:3]]
  return f'<div class="page-workspace" data-page-scene="{kind}"><div class="scene-top"><b>{dict(sales="Görüşme listeniz",fields="İşletme bilgileri",batch="Toplu araştırma",csv="Liste önizlemesi")[kind]}</b><span>3 örnek kayıt</span></div><div class="workspace-query"><span>{"Şişli · Diş klinikleri" if kind=="sales" else "Beyoğlu · Mimarlık ofisleri"}</span><b data-batch-label>Toplu araştır</b></div><div class="workspace-head"><span>İŞLETME</span><span>İLETİŞİM BİLGİLERİ</span></div>'+''.join(f'<div class="workspace-record" data-record><i>{n[0]}</i><div><b>{n}</b><small>{"Diş kliniği · Şişli" if kind=="sales" else records[i][3]+" · Beyoğlu"}</small><span>+90 (212) 000 10 0{i+1}</span><span>{"klinik-"+str(i+1)+".example" if kind=="sales" else records[i][2]}</span></div><em>✓</em></div>' for i,n in enumerate(names))+'<div class="workspace-footer"><span><b data-count>3</b> / 3 kayıt</span><strong>CSV olarak hazır ↗</strong></div><p class="scene-note">İşletme adları ve iletişim bilgileri örnektir.</p></div>'
 return ''
add('nasil-calisir','Veri Burada nasıl çalışır? | Toplu işletme araştırması','Bölge ve sektör seçiminden toplu veri toplamaya, işletme listenizi incelemekten CSV indirmeye kadar Veri Burada ürün akışını keşfedin.','Bir bölge seçin.<br><em>Listenizi oluşturun.</em>','İşletmeleri tek tek not almayın. Aramanızı belirleyin, bilgileri birlikte toplayın ve düzenli listenizi indirin.',block('Dört adımda ilk listeniz.',cards([('Bölgenizi belirleyin.','Çalışmak istediğiniz il ve ilçeyi seçin. İlk araştırmayı küçük bir bölgeyle başlatmak, sonuçları değerlendirmenizi kolaylaştırır.','',''),('İşletme türünü seçin.','Kuaför, kafe ya da mimarlık ofisi: sunduğunuz hizmete uygun sektörü belirleyin.','',''),('Bilgileri topluca alın.','Araştırmayı tek işlemle başlatın. İşletmelerin profilinde paylaşılan bilgiler çalışma listenizde bir araya gelsin.','',''),('İnceleyin, CSV indirin.','Telefon, adres ve web sitesi sütunlarını kontrol edin. Listenizi elektronik tablo uygulamanızda açın.','listeler','Çıktıyı inceleyin')]))+block('Liste hazır. Sonraki adım size ait.',paras('Veri Burada işletme araştırmasını düzenler; hangi işletmeye, ne zaman ve hangi teklifle ulaşacağınıza siz karar verirsiniz. Bir kayıt, otomatik olarak doğrulanmış satış fırsatı anlamına gelmez.','İletişim kurmadan önce işletme profilini, bilgilerin güncelliğini ve teklifinizin uygunluğunu kontrol edin.')),'story')
add('ozellikler','İşletme araştırması ve CSV özellikleri | Veri Burada','Google Haritalar işletme bilgilerini bölge ve sektöre göre araştırın. Telefon, web sitesi, adres ve konum alanlarını bir listede inceleyin.','Araştırmanız dağılmasın.<br><em>Bilgiler bir arada kalsın.</em>','Bir bölge, bir sektör, düzenli bir çalışma listesi. Veri Burada işletme araştırmasının tekrar eden adımlarını bir araya getirir.',block('Listede ne göreceksiniz?',cards([('İşletme kimliği','Adı ve işletme türü sayesinde hangi kayıtla çalıştığınızı görün. Aynı isimdeki işletmeleri konumlarıyla birlikte değerlendirin.','',''),('Telefon ve web sitesi','İşletme profilinde paylaşılan iletişim alanlarını tek tabloda inceleyin. Eksik alanları araştırmanız sırasında belirleyin.','',''),('Adres ve konum','İl, ilçe, açık adres ve mevcut konum bilgileriyle bölgenize uygun bir çalışma listesi hazırlayın.','',''),('CSV çıktısı','Listenizi indirin; Excel, Google Sheets veya CSV kabul eden çalışma aracınızda açın.','blog/isletme-listesini-excelde-duzenleme','CSV rehberini okuyun')]))+block('Toplu toplama. Düzenli inceleme.',paras('Her işletme için ayrı ayrı kopyala ve yapıştır yapmak yerine, aramanızdaki işletme bilgilerini birlikte toplayın. Çıktıda yer alan alanların doluluğu kaynak işletme profiline bağlıdır.','İşletmeler bilgilerini güncellediğinde kayıtlarda farklılık olabilir. Listenin tamamını kullanmadan önce ilgili alanları kontrol etmeniz gerekir.')),'fields')
add('kullanim-alanlari/satis-ekipleri','Satış ekipleri için işletme listeleri | Veri Burada','Bölge ve sektöre göre potansiyel müşteri olabilecek işletmeleri araştırın. Telefon, web sitesi ve adres bilgileriyle görüşme listenizi hazırlayın.','Yeni görüşmeler için<br><em>iyi bir başlangıç listesi.</em>','Bölgenizdeki işletmeleri araştırın. Telefon, adres ve web bilgileri tek yerdeyken ekibinizin bir sonraki adımı daha net olsun.',block('Listeniz, satış sürecinizin başlangıcı.',cards([('Hedef bölgenizi daraltın.','Bir şehir yerine belirli ilçelerle başlayın. Ekibinizin ulaşabileceği bölgeyi ve sunduğunuz hizmete uygun işletme türünü seçin.','',''),('Bilgileri birlikte inceleyin.','İşletme kimliği, telefon, web sitesi ve adresi yan yana görün. İletişimden önce işletmeyi tanımak için web sitesini inceleyin.','',''),('Ekibinizle aynı tabloda çalışın.','CSV çıktısına sorumlu kişi, araştırma notu ve sonraki adım sütunları ekleyin. Veri Burada bu aşamada arama ya da mesaj göndermez.','blog/bolgeye-gore-musteri-arastirmasi','Araştırma rehberini okuyun')]))+block('Daha çok kayıt her zaman daha iyi liste demek değildir.',paras('İlk denemede küçük bir sektör ve bölgeyle başlayın. Örnek kayıtları inceleyerek aramanızın hedef kitlenize uyup uymadığını kontrol edin.','Ulaşacağınız işletmenin size uygunluğu, iletişim bilgileri ve ticari iletişim koşulları ayrı ayrı değerlendirilmelidir.')),'sales')
add('kullanim-alanlari/ajanslar','Ajanslar için sektör ve işletme araştırması | Veri Burada','Ajansınız için işletmeleri bölge ve sektöre göre araştırın. Web sitelerini, telefonlarını ve adreslerini inceleyerek teklif öncesi hazırlığınızı yapın.','Tekliften önce<br><em>işletmeyi tanıyın.</em>','Restoranlardan kliniklere: aynı sektördeki işletmelerin web ve iletişim bilgilerini bir arada inceleyin. Teklifinizi araştırmanız şekillendirsin.',block('Bir alan adı, araştırmanın sadece başlangıcı.',cards([('Aynı sektörü karşılaştırın.','Bir bölgedeki aynı tür işletmeleri incelemek, hizmetinizi hangi ihtiyaca göre anlatacağınızı düşünmenize yardımcı olur.','',''),('Web sitesini gerçekten inceleyin.','Bir web adresinin bulunması, sitenin iyi ya da kötü olduğu anlamına gelmez. Mobil deneyimi, içerikleri ve iletişim yollarını kendiniz değerlendirin.','',''),('Görüşmeye hazırlıklı gidin.','Bulduğunuz bilgileri çalışma listenize alın. Genel bir mesaj yerine işletmeye uygun gözlemler ve somut bir öneri hazırlayın.','blog/ajanslar-icin-isletme-arastirmasi','Ajans rehberini okuyun')]))+block('Veriden, işletmeye özel bir öneriye.',paras('Veri Burada, işletme profillerinde paylaşılan bilgileri toplar. Otomatik site kalite puanı, SEO denetimi veya müşteri kazanma garantisi sunmaz.','Görseldeki iki restoran için hazırlanmış örnek site tasarımları, web ve iletişim alanlarının araştırma sırasında birlikte nasıl değerlendirilebileceğini gösterir.')),'agency')
add('kullanim-alanlari/yerel-isletmeler','Yerel işletmeler için bölgesel araştırma | Veri Burada','Çevrenizdeki işletmeleri bölge ve sektöre göre bulun. İş birliği, tedarik ve yerel pazar araştırmanız için düzenli bir liste oluşturun.','Yakınınızdaki işletmeler.<br><em>Yeni iş birlikleri.</em>','Mahallenizde ve çevre ilçelerde kimler var? İşletmeleri konumları ve iletişim bilgileriyle birlikte inceleyin.',block('Kendi bölgenizden başlayın.',cards([('İş birliği adayları','Birbirini tamamlayan hizmetler sunan işletmeleri araştırın. Bir kafenin çevresindeki ofisler veya bir atölyenin yakınındaki tasarım mağazaları iyi başlangıçlar olabilir.','',''),('Bölgesel pazar araştırması','Seçtiğiniz sektörde hangi işletmelerin bulunduğunu inceleyin. Bu listeyi bölgedeki talebin veya pazar büyüklüğünün kesin ölçümü olarak değerlendirmeyin.','',''),('Tedarik araştırması','İhtiyacınız olan işletme türünü belirleyin. İletişime geçmeden önce hizmet bölgesi, ürün ve çalışma koşullarını ilgili işletmeden doğrulayın.','listeler','Liste örneğini görün')]))+block('Konum, bağlam kazandırır.',paras('Aynı isimdeki iki işletmeyi adresleriyle ayırın. Yakınlık ve hizmet alanı gibi kararlar için haritayı ve işletmenin kendi bilgilerini birlikte kullanın.','Veri Burada haritada görünen işletmelerin listesini hazırlamanıza yardımcı olur; rotalama veya mesafe optimizasyonu yapıldığı anlamına gelmez.')),'local')
add('listeler','İşletme listesi ve dolu CSV örneği | Veri Burada','Veri Burada işletme listesi örneğini inceleyin. İşletme adı, telefon, web sitesi ve adres sütunlarından oluşan dolu örnek CSV dosyasını indirin.','Çıktıyı görün.<br><em>Sonra karar verin.</em>','İndirilen dosyada ne göreceğinizi önce burada inceleyin. Düzenli sütunlar, okunabilir kayıtlar ve kendi çalışma şeklinize uyarlayabileceğiniz bir CSV.', '<section class="directory-section"><div class="directory-tools"><div><h2>İşletme listeniz nasıl görünür?</h2><p>5 dolu örnek kayıt · Mimarlık ofisleri · Beyoğlu</p></div><button class="button primary" data-download-sample>Örnek CSV’yi indir ↓</button></div>'+sheet()+'<p class="scene-note">Bu dosya örnek kayıtlar içerir. İşletme adları, .example alan adları ve 000 içeren telefonlar gerçek iletişim bilgileri değildir.</p></section>'+block('Listenizi işinize göre düzenleyin.',cards([('Önce bilgileri kontrol edin.','İsimleri, konumları ve iletişim alanlarını inceleyin. Gerçek çalışmanızda eksik ya da değişmiş bilgilerle karşılaşabilirsiniz.','',''),('Kendi sütunlarınızı ekleyin.','Araştırma notu, sorumlu kişi veya sonraki görüşme tarihi gibi sütunlarla listenizi çalışma dosyanıza dönüştürün.','',''),('CSV’yi kolayca açın.','Türkçe karakterler için UTF-8 kullanın. Sütunlar tek hücrede görünüyorsa içe aktarma sırasında noktalı virgül ayırıcısını seçin.','blog/isletme-listesini-excelde-duzenleme','Excel rehberine geçin')])),'csv')
prices=[(1,'499','499,00'),(3,'999','333,00'),(6,'1.499','249,83'),(12,'2.499','208,25')]
add('pricing','Veri Burada fiyatları | 1, 3, 6 ve 12 aylık lisans','Veri Burada kullanım sürelerini karşılaştırın. 1, 3, 6 ve 12 aylık lisans seçenekleri, toplam fiyatlar ve aylık karşılıkları tek sayfada.','İşinize uygun süre.<br><em>Aynı özellikler.</em>','Önce örnek listeyi inceleyin, sonra ihtiyacınıza uygun kullanım süresini seçin. Her pakette aynı işletme araştırması ve CSV özellikleri.', '<section><div class="license-grid">'+''.join(f'<article class="license-card {"featured" if m==6 else ""}"><span>{"UZUN VADELİ ARAŞTIRMA" if m==6 else "KULLANIM LİSANSI"}</span><h2>{m} ay</h2><div class="license-price">₺{v}<small>/ toplam</small></div><p>Aylık karşılığı ₺{avg}</p><ul><li>Veri Burada tarayıcı eklentisi</li><li>Sınırsız işletme toplama</li><li>{m} ay kullanım süresi</li><li>CSV olarak indirme</li></ul><a class="button {"primary" if m==6 else "secondary"}" href="/iletisim/?plan={m}">Lisans için bilgi alın ↗</a></article>' for m,v,avg in prices)+'</div><p class="scene-note">Ödeme bu sitede alınmaz. Seçtiğiniz süre için iletişime geçerek güncel satın alma bağlantısını ve koşullarını isteyebilirsiniz.</p></section>'+block('Satın almadan önce.',faq([('Paketler arasında özellik farkı var mı?','Mevcut paketlerde kullanım süresi değişir. Eklenti, işletme toplama ve CSV çıktısı tüm sürelerde yer alır.'),('Aktivasyon nasıl ilerliyor?','Resmî ürün sayfasında satın alımdan sonra 24 saat içinde aktivasyon ve e-posta ile bilgilendirme belirtilmektedir. Satın alma ekranındaki güncel bilgileri kontrol edin.'),('Burada kart bilgilerimi girecek miyim?','Hayır. Bu landing ödeme almaz. Lisans düğmeleri, seçtiğiniz süreyle birlikte iletişim sayfasını açar.'),('Önce örnek görebilir miyim?','Evet. Örnek listeler sayfasında dolu kayıtları inceleyebilir ve örnek CSV’yi indirebilirsiniz.')])) )
add('eklenti-indir','Veri Burada eklenti kurulumu | Chrome ve Chromium tarayıcılar','Veri Burada tarayıcı eklentisini indirme ve kurma adımlarını öğrenin. ZIP dosyası, uzantılar ekranı ve ilk arama için kurulum rehberi.','Tarayıcınıza ekleyin.<br><em>İlk listenize geçin.</em>','Windows veya macOS üzerinde desteklenen Chromium tarayıcılarla başlayın. Kurulum dosyasını resmî indirme sayfasından alın.', '<div class="download-callout"><div><h2>Kurulum dosyası</h2><p>Kurulum dosyası için bize yazın; desteklenen tarayıcı ve kurulum adımlarını aşağıda inceleyin.</p></div><a class="button primary" href="mailto:destek@veriburada.com?subject=Veri%20Burada%20kurulum%20dosyasi">Kurulum dosyasını iste ↗</a></div>'+block('Kurulumu adım adım tamamlayın.','<ol class="setup-list">'+''.join(f'<li><span>0{i+1}</span><div><h3>{t}</h3><p>{b}</p></div></li>' for i,(t,b) in enumerate([('ZIP dosyasını indirin.','Resmî indirme sayfasındaki dosyayı bilgisayarınıza kaydedin. Bu sayfa sizin adınıza dosya indirip uzantı yüklemez.'),('Dosyayı bir klasöre çıkarın.','ZIP dosyasını açın ve içeriğini kalıcı bir klasöre çıkarın. Eklentiyi kullanırken bu klasörü silmeyin.'),('Uzantılar ekranını açın.','Chrome’da adres çubuğuna chrome://extensions yazın. Edge kullanıyorsanız edge://extensions adresini açın.'),('Klasörü tarayıcıya yükleyin.','Geliştirici modunu açın, “Paketlenmemiş öğe yükle” seçeneğiyle çıkardığınız eklenti klasörünü seçin.'),('Hesabınızı ve ilk aramanızı hazırlayın.','Google Haritalar’ı açın. Veri Burada panelinde hesabınızla ilerleyin; il, ilçe ve işletme türünü seçerek ilk araştırmanızı başlatın.')]))+'</ol>')+block('Kurulum sırasında takıldınız mı?',paras('Tarayıcınızın güncel olduğundan ve ZIP dosyasını çıkardıktan sonra doğru klasörü seçtiğinizden emin olun. Hesap veya lisansla ilgili sorunlarda işlem bilgilerinizi herkese açık alanlarda paylaşmayın.')+link('iletisim','Destek seçeneklerini inceleyin')),'install')
add('hakkimizda','Veri Burada hakkında | İşletme araştırmasını düzenleyin','Veri Burada, bölge ve sektöre göre işletme araştırmasını ve CSV listeleri oluşturmayı kolaylaştıran bir tarayıcı eklentisidir.','Araştırmadan<br><em>çalışma listesine.</em>','Veri Burada, işletme bilgilerini farklı sekmelerden tek tek kopyalamanın yerine daha düzenli bir çalışma şekli sunmak için tasarlandı.', '<figure class="about-image"><img src="/media/office.webp" width="1100" height="734" alt="Aydınlık ortak çalışma alanı, temsili fotoğraf" loading="lazy"/><figcaption>İyi düzenlenmiş bir çalışma alanı gibi: bilgiler de yerli yerinde olsun. Temsili fotoğraf.</figcaption></figure>'+block('Ne yapıyoruz?',paras('Google Haritalar’daki işletmeleri bölge ve sektöre göre araştırmanıza, profillerde paylaşılan bilgileri toplamanıza ve CSV olarak düzenli bir listeye dönüştürmenize yardımcı oluyoruz.','Satış ekipleri, ajanslar ve yerel işletmeler aynı bilgiye farklı amaçlarla bakar. Bu yüzden çalışma akışını bir sektörle sınırlamak yerine, aramanın başında hedefinizi belirlemenizi önemsiyoruz.'))+block('Nasıl bir ürün olmak istiyoruz?',cards([('Anlaşılır','Ürün ne yapıyorsa onu anlatan, çıktısını satın almadan önce görebildiğiniz bir deneyim.','',''),('Düzenli','İşletme kimliği, iletişim ve konum alanlarının tek yerde olduğu, farklı çalışma araçlarına taşınabilen listeler.','',''),('Sınırları açık','Alanların kaynak profile bağlı olduğunu, örneklerin gerçek kayıt olmadığını ve araştırmadan sonraki kararın size ait olduğunu açıkça belirten içerik.','','')])) )
faqs=[('Veri Burada ne yapar?','Google Haritalar’daki işletmeleri bölge ve sektöre göre araştırmanıza, profil bilgilerini topluca listelemenize ve CSV olarak indirmenize yardımcı olur.'),('Hangi bilgiler listelenebilir?','İşletme adı, türü, telefon, web sitesi, açık adres, konum, puan ve yorum sayısı gibi kaynak profilde paylaşılan alanlar listelenebilir. Her kayıt tüm alanları içermeyebilir.'),('İşletmeleri tek tek mi ekliyorum?','Hayır. Bölge ve işletme türü seçildikten sonra toplama işlemi birlikte başlatılır. Animasyonlardaki pinler arama sonuçlarını görselleştirir.'),('Telefonda eklentiyi kullanabilir miyim?','Bu landing ve örnek akışlar mobilde görüntülenebilir. Eklentinin kurulumu desteklenen masaüstü Chromium tarayıcıları içindir.'),('CSV dosyasını Excel’de açabilir miyim?','Evet. Veri içe aktarma seçeneğiyle UTF-8 kodlamasını ve dosyanın ayırıcısını seçebilirsiniz. Örnek dosyamız noktalı virgül kullanır.'),('İlk beş kayıt önizlemesi gerçek arama mı?','Mevcut landing önizlemesi örnek modda çalışır. Sonuç ekranı örnek kayıtları açıkça belirtir. Gerçek arama bağlantısı etkinleştirildiğinde yanıtlar bağlı hizmetten gelir.'),('Veri Burada otomatik mesaj gönderir mi?','Bu ürün anlatımı işletme araştırması ve CSV çıktısını kapsar. İşletmelere otomatik arama, e-posta veya mesaj gönderilmez.'),('Listedeki bilgiler güncel ve eksiksiz mi?','Alanların doluluğu ve güncelliği işletmenin kaynak profiline bağlıdır. İletişime geçmeden önce bilgileri doğrulamanız gerekir.')]
add('sss','Sık sorulan sorular | Veri Burada','Veri Burada kurulumu, toplu işletme toplama, CSV, mobil kullanım ve örnek arama hakkında sık sorulan sorulara yanıt bulun.','Aklınızdaki sorular.<br><em>Açık yanıtlar.</em>','Ürünü kullanmadan önce ne yapabildiğini, neye ihtiyaç duyduğunu ve çıktının nasıl çalıştığını öğrenin.',faq(faqs)+block('Yanıtını bulamadığınız bir konu mu var?',paras('Kurulum, kullanım veya lisans hakkında sorularınız için iletişim sayfasını inceleyin. Ekran görüntüsü paylaşırken kişisel bilgilerinizi ve erişim anahtarlarını gizleyin.')+link('iletisim','İletişime geçin')),faqs=faqs)
add('iletisim','İletişim ve destek | Veri Burada','Veri Burada kurulum, işletme araştırması, CSV ve lisans soruları için destek hazırlığı ve sık sorulan sorular.','Nerede takıldınız?<br><em>Birlikte netleştirelim.</em>','Kurulum, arama veya dosya çıktısı: sorununuzu birkaç ayrıntıyla anlatmak çözümü kolaylaştırır.',cards([('Kurulum soruları','Tarayıcınızın adını, işletim sisteminizi ve hangi adımda durduğunuzu not edin.','eklenti-indir','Kurulum adımlarını görün'),('CSV ve liste soruları','Dosyayı hangi uygulamada açtığınızı ve sorunun sütunlar mı Türkçe karakterler mi olduğunu belirtin.','blog/isletme-listesini-excelde-duzenleme','CSV rehberini okuyun'),('Ürün ve lisans','Paket kapsamını ve süreleri fiyatlandırma sayfasından karşılaştırın. Kart bilgilerinizi destek notuna yazmayın.','pricing','Paketleri inceleyin')])+'<section class="support-compose"><div><h2>Destek notunuzu hazırlayın.</h2><p>Bu araç mesaj göndermez. Hazırladığınız notu indirip destek görüşmenizde kullanabilirsiniz.</p></div><form id="support-note"><label>Konu<select name="subject"><option>Kurulum</option><option>Arama ve liste</option><option>CSV dosyası</option><option>Lisans</option><option>Diğer</option></select></label><label>Ne oldu?<textarea name="message" rows="5" required minlength="10" placeholder="Hangi adımda, ne olmasını bekliyordunuz? Şifre veya ödeme bilgisi yazmayın."></textarea></label><button class="button primary" type="submit">Destek notunu indir ↓</button><p id="support-status" role="status"></p></form></section>',noindex=True)

